const $=id=>document.getElementById(id),app=$('app'),ABC=[...'ABCDEFGHIJKLMNÑOPQRSTUVWXYZ'],DB='roscolab.v1.collection',THEME='roscolab.v1.theme',clone=x=>JSON.parse(JSON.stringify(x)),esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c])),norm=x=>String(x??'').toLocaleLowerCase('es').replace(/ñ/g,'\uE000').normalize('NFD').replace(/[\u0300-\u036f]/g,'').replace(/\uE000/g,'ñ').replace(/[^\p{L}\p{N}]/gu,''),uid=()=>globalThis.crypto?.randomUUID?.()||Date.now().toString(36)+Math.random().toString(36).slice(2),read=(k,d)=>{try{return JSON.parse(localStorage.getItem(k))??d}catch{return d}},write=(k,v)=>{try{localStorage.setItem(k,JSON.stringify(v));return true}catch{return false}},colors={'Tecnología y Digitalización':'#087c91','Matemáticas':'#2563eb','Lengua y Literatura':'#bd3650','Geografía e Historia':'#aa6720','Biología y Geología':'#16834a','Física y Química':'#7c3aed','Inglés':'#4f46e5','Francés':'#be357c','Educación Física':'#648018','Educación Plástica':'#c45119','Música':'#8a45aa','Andalucía':'#00843d','Cultura general':'#475569','Otra':'#4f46e5'},courses=['Infantil','1º Primaria','2º Primaria','3º Primaria','4º Primaria','5º Primaria','6º Primaria','1º ESO','2º ESO','3º ESO','4º ESO','1º Bachillerato','2º Bachillerato','Formación Profesional','Educación Permanente','Todos los niveles','Otro'],catalog=JSON.parse($('catalog').textContent),portable=!!catalog.portable,library=catalog.games||[];
let mine=portable?[]:read(DB,[]);if(!Array.isArray(mine))mine=[];let draft=null,editLevel=0,editBank=0,game=null,timer=null,view='',dirty=false,toastTimer;const byId=id=>[...mine,...library].find(x=>x.id===id),options=(arr,selected)=>arr.map(x=>`<option ${x===selected?'selected':''}>${esc(x)}</option>`).join(''),field=(label,id,val='',type='text')=>`<label class="field"><span>${esc(label)}</span><input id="${id}" type="${type}" value="${esc(val)}"></label>`,sel=(label,id,arr,val)=>`<label class="field"><span>${esc(label)}</span><select id="${id}">${options(arr,val)}</select></label>`,check=(id,label,checked=false)=>`<label class="row"><input type="checkbox" id="${id}" ${checked?'checked':''}>${esc(label)}</label>`,head=(k,t,d)=>`<div class="pagehead"><div class="eyebrow muted">${k}</div><h1>${t}</h1><p class="muted">${d}</p></div>`,act=(name,fn)=>{const el=$(name);if(el)el.addEventListener('click',fn)},val=id=>$(id).value,download=(name,content,type='application/json')=>{let u=URL.createObjectURL(new Blob([content],{type})),a=document.createElement('a');a.href=u;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(u),1000)},slug=s=>norm(s).slice(0,70)||'rosco',qblank=l=>({letter:l,mode:'starts',clue:'',answer:'',fact:'',aliases:[]}),count=r=>r.levels.reduce((n,l)=>n+l.banks.reduce((m,b)=>m+b.questions.length,0),0),accent=r=>{document.documentElement.style.setProperty('--accent',r?.color||'#4f46e5')};
function toast(s){$('toast').textContent=s;$('toast').classList.remove('hidden');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.add('hidden'),4000)}function persist(){return write(DB,mine)}function go(v,force=false){if(view==='ai'&&directJob){if(!force&&!confirm('Hay una generación en curso. ¿Cancelar y salir?'))return;directJob.abort();directJob=null;}if(!force&&view==='editor'&&dirty&&!confirm('Hay cambios sin guardar. ¿Salir del editor?'))return;if(!force&&view==='game'&&game&&!game.finished&&!confirm('¿Abandonar esta partida?'))return;clearInterval(timer);timer=null;view=v;document.body.classList.remove('pdi');accent();document.querySelectorAll('[data-nav]').forEach(b=>b.classList.toggle('active',b.dataset.nav===v));({home,library:()=>list(false),mine:()=>list(true),editor:()=>{if(!draft)draft=newRosco();renderEditor()},ai:renderAI,help,setup:renderSetup,game:renderGame,result:renderResult}[v]||home)();window.scrollTo(0,0)}
function newRosco(letters=ABC,levels=1,banks=1){return {schema:'roscolab.v1',id:uid(),title:'Mi nuevo rosco',subject:'Otra',course:'3º ESO',author:'',description:'',color:'#4f46e5',letters:[...letters],levels:Array.from({length:levels},(_,i)=>({name:['Básico','Intermedio','Avanzado','Experto'][i],banks:Array.from({length:banks},(_,j)=>({name:`Banco ${String.fromCharCode(65+j)}`,questions:letters.map(qblank)}))}))}}
function fits(q,a=q.answer){const w=norm(a),l=norm(q.letter);return !!w&&(q.mode==='starts'?w.startsWith(l):w.includes(l))}function issues(r){let out=[];for(let i=0;i<r.levels.length;i++){let across=new Map();for(let j=0;j<r.levels[i].banks.length;j++){let seen=new Set();for(const q of r.levels[i].banks[j].questions){const label=`${r.levels[i].name} / ${r.levels[i].banks[j].name} / ${q.letter}`;if(!q.clue.trim()||!q.answer.trim())out.push({label,msg:'Falta pregunta o respuesta',hard:true});else if(!fits(q))out.push({label,msg:'La respuesta no cumple la letra',hard:true});if(q.aliases.some(a=>!fits(q,a)||!norm(a)||norm(q.answer)!==norm(a)&&norm(q.answer).startsWith(norm(a))))out.push({label,msg:'Alternativa inválida o incompleta',hard:true});let n=norm(q.answer);if(n&&seen.has(n))out.push({label,msg:'Respuesta repetida en el banco',hard:true});if(n&&across.has(n)&&across.get(n)!==j)out.push({label,msg:'Respuesta repetida entre bancos del nivel',hard:false});if(n){seen.add(n);across.set(n,j)}}}}return out}
function normalize(raw){if(raw&&raw.rosco)raw=raw.rosco;if(raw&&raw['1']?.green){const old=raw;raw={title:'Rosco importado',subject:'Otra',course:'Todos los niveles',letters:ABC,levels:Object.keys(old).filter(k=>/^\d+$/.test(k)).map(k=>({name:`Nivel ${k}`,banks:[{name:'Banco A',questions:old[k].green},{name:'Banco B',questions:old[k].white}]}))}}if(!raw||!Array.isArray(raw.letters)||!Array.isArray(raw.levels))throw Error('El JSON no contiene letters y levels. Utiliza el formato Rosco LAB.');const letters=raw.letters.map(l=>String(l).toUpperCase());if(letters.length<2||letters.length>27||new Set(letters).size!==letters.length||letters.some(l=>!ABC.includes(l)))throw Error('Selecciona de 2 a 27 letras españolas diferentes.');if(raw.levels.length<1||raw.levels.length>4)throw Error('Se admiten de 1 a 4 niveles.');let r={schema:'roscolab.v1',id:uid(),title:String(raw.title||'Rosco importado').slice(0,120),subject:String(raw.subject||'Otra').slice(0,80),course:String(raw.course||'Todos los niveles').slice(0,80),author:String(raw.author||'').slice(0,100),description:String(raw.description||'').slice(0,1000),color:/^#[0-9a-f]{6}$/i.test(raw.color)?raw.color:colors[raw.subject]||'#4f46e5',letters,levels:[]};r.levels=raw.levels.map((l,i)=>{if(!Array.isArray(l.banks)||l.banks.length<1||l.banks.length>4)throw Error(`Nivel ${i+1}: se admiten 1–4 bancos.`);return {name:String(l.name||`Nivel ${i+1}`).slice(0,80),banks:l.banks.map((b,j)=>{if(!Array.isArray(b.questions))throw Error('Falta questions en un banco.');let qs=b.questions;if(qs.length!==letters.length||new Set(qs.map(q=>String(q.letter).toUpperCase())).size!==letters.length||qs.some(q=>!letters.includes(String(q.letter).toUpperCase())))throw Error(`Nivel ${i+1}, banco ${j+1}: debe haber exactamente una pregunta por letra.`);return {name:String(b.name||`Banco ${j+1}`).slice(0,80),questions:letters.map(letter=>{let q=qs.find(q=>String(q.letter).toUpperCase()===letter);if(!['starts','contains'].includes(q.mode))throw Error(`Letra ${letter}: mode debe ser starts o contains.`);return {letter,mode:q.mode,clue:String(q.clue??'').slice(0,4000),answer:String(q.answer??'').slice(0,300),fact:String(q.fact??'').slice(0,4000),aliases:Array.isArray(q.aliases)?q.aliases.map(String).slice(0,20):[],source:String(q.source??'').slice(0,300)}})}})}});return r}
function wheelArt(){return `<svg viewBox="0 0 320 280" role="img" aria-label="Rosco multicolor de letras"><circle cx="160" cy="140" r="112" fill="none" stroke="#ffffff20" stroke-width="2"/><circle cx="160" cy="140" r="88" fill="#ffffff09"/>${ABC.map((l,i)=>{let a=i*2*Math.PI/ABC.length-Math.PI/2,x=160+112*Math.cos(a),y=140+112*Math.sin(a);return `<circle cx="${x}" cy="${y}" r="11" fill="${['#65d8e7','#929bff','#b2f0c9','#f9d285'][i%4]}"/><text x="${x}" y="${y+4}" text-anchor="middle" font-size="12" font-weight="800" fill="#15213a">${l}</text>`}).join('')}<text x="160" y="135" text-anchor="middle" fill="white" font-size="28" font-weight="800">¡A JUGAR!</text><text x="160" y="158" text-anchor="middle" fill="#c1d7f6" font-size="12">TODAS LAS MATERIAS</text></svg>`}
function card(r,personal=false){let n=issues(r).filter(x=>x.hard).length;return `<article class="tile" data-color style="--tile-color:${esc(r.color)}"><div class="row between"><span class="pill">${esc(r.subject)}</span><span class="muted">${r.letters.length} letras</span></div><h3>${esc(r.title)}</h3><p>${esc(r.description||r.course)}</p><div class="row"><span class="pill">${esc(r.course)}</span><span class="pill">${count(r)} preguntas</span><span class="pill">${r.levels.length} nivel(es)</span></div>${n?`<small class="error">Borrador: ${n} incidencias</small>`:''}<div class="row"><button class="primary" data-play="${esc(r.id)}" ${n?'disabled':''}>Jugar</button><button data-edit="${esc(r.id)}">${personal?'Editar':'Duplicar'}</button>${personal?`<button data-export="${esc(r.id)}">JSON</button><button class="danger" data-delete="${esc(r.id)}">Eliminar</button>`:''}</div>${r.id==='andalucia'&&!portable?'<a href="andalucia/index.html">Abrir edición 4D original ↗</a>':''}</article>`}
function bindCards(){app.querySelectorAll('[data-play]').forEach(b=>b.onclick=()=>setup(byId(b.dataset.play)));app.querySelectorAll('[data-edit]').forEach(b=>b.onclick=()=>{let r=byId(b.dataset.edit);draft=clone(r);if(!mine.some(x=>x.id===r.id)){draft.id=uid();draft.title+=' · copia'}editLevel=editBank=0;dirty=false;go('editor',true)});app.querySelectorAll('[data-export]').forEach(b=>b.onclick=()=>exportJSON(byId(b.dataset.export)));app.querySelectorAll('[data-delete]').forEach(b=>b.onclick=()=>{if(confirm('¿Eliminar este rosco guardado?')){mine=mine.filter(r=>r.id!==b.dataset.delete);if(!persist())toast('No se pudo actualizar el almacenamiento.');list(true)}})}
function home(){app.innerHTML=`<section class="hero"><div><div class="eyebrow">Tu aula · tus preguntas · tu juego</div><h1>Crea. Juega.<br>Aprende.</h1><p>Convierte cualquier contenido en un rosco interactivo. Diseña tus preguntas, adapta juegos y prepara retos para tu clase.</p><div class="row"><button class="primary" id="heroPlay">Explorar roscos →</button><button class="secondary" id="heroCreate">Crear mi rosco</button><button class="secondary" id="heroPDF">Crear desde PDF</button></div></div>${wheelArt()}</section><div class="section-title"><div><h2>¿Qué quieres hacer hoy?</h2><p class="muted">Herramientas pensadas para el profesorado.</p></div></div><div class="grid">${[['◉','Jugar a un rosco','Descubre los juegos listos para usar.','library'],['✎','Crear manualmente','Personaliza letras, preguntas y niveles.','editor'],['✦','Crear con IA','Sube un PDF y genera preguntas o utiliza un prompt.','ai'],['▤','Mis roscos','Guarda, edita y exporta tus creaciones.','mine']].map(([s,t,d,n])=>`<article class="tile"><div class="symbol">${s}</div><h3>${t}</h3><p>${d}</p><button data-home="${n}">Abrir →</button></article>`).join('')}</div><div class="section-title"><div><h2>Roscos destacados</h2><p class="muted">Una biblioteca para todas las materias.</p></div><button id="all">Ver todos</button></div><div class="grid">${library.slice(0,4).map(r=>card(r)).join('')}</div>`;act('heroPlay',()=>go('library'));act('heroPDF',()=>go('ai'));act('heroCreate',()=>create());act('all',()=>go('library'));app.querySelectorAll('[data-home]').forEach(b=>b.onclick=()=>b.dataset.home==='editor'?create():go(b.dataset.home));bindCards()}
function list(personal){let arr=personal?mine:library;app.innerHTML=head(personal?'Tu espacio':'Recursos educativos',personal?'Mis roscos':'Biblioteca de roscos',personal?'Guardados en este navegador. Exporta copias para conservarlos y compartirlos.':'Juegos preparados para usar o duplicar y adaptar.')+`<div class="panel row no-print"><input id="search" placeholder="Buscar por tema, materia, curso…" style="flex:2;min-width:180px"><select id="filter" style="flex:1;min-width:150px"><option value="">Todas las materias</option>${options([...new Set(arr.map(x=>x.subject))])}</select><button class="primary" id="create">+ Crear rosco</button><button id="import">Importar JSON</button><input type="file" id="file" accept=".json,application/json" hidden></div><div id="results" class="grid" style="margin-top:16px"></div>`;function render(){let s=norm(val('search')),f=val('filter');let items=arr.filter(r=>(!f||r.subject===f)&&norm([r.title,r.subject,r.course,r.description,r.author].join(' ')).includes(s));$('results').innerHTML=items.length?items.map(r=>card(r,personal)).join(''):'<div class="panel">No hay roscos que coincidan. Crea uno nuevo o importa un archivo.</div>';bindCards()}$('search').oninput=render;$('filter').onchange=render;act('create',create);act('import',()=>$('file').click());$('file').onchange=async()=>{try{importText(await $('file').files[0].text())}catch(e){toast(e.message)}};render()}
function create(){if(view==='editor'&&dirty&&!confirm('¿Descartar cambios sin guardar?'))return;draft=newRosco();editLevel=editBank=0;dirty=false;go('editor',true)}
function lettersHTML(letters){return `<div class="letterpick" id="letterpick">${ABC.map(l=>`<label><input type="checkbox" value="${l}" ${letters.includes(l)?'checked':''} aria-label="Letra ${l}">${l}</label>`).join('')}</div><div class="row" style="margin-top:8px"><button id="lettersAll">27 letras</button><button id="lettersEasy">23 sin K, W, X, Ñ</button><button id="lettersShort">10 letras</button></div>`}function bindLetters(){for(const [id,ls] of [['lettersAll',ABC],['lettersEasy',ABC.filter(l=>!['K','W','X','Ñ'].includes(l))],['lettersShort',[...'ABCDEFGHIJ']]])act(id,()=>{app.querySelectorAll('#letterpick input').forEach(x=>x.checked=ls.includes(x.value));if(view==='ai')updatePrompt()})}function picked(){return ABC.filter(l=>[...app.querySelectorAll('#letterpick input:checked')].some(x=>x.value===l))}
function syncEditor(){if(!$('edTitle'))return;draft.title=val('edTitle').trim()||'Mi nuevo rosco';draft.subject=val('edSubject');draft.course=val('edCourse');draft.author=val('edAuthor');draft.description=val('edDescription');draft.color=val('edColor');let lv=draft.levels[editLevel],bank=lv.banks[editBank];lv.name=val('levelName')||`Nivel ${editLevel+1}`;bank.name=val('bankName')||`Banco ${editBank+1}`;app.querySelectorAll('tr[data-q]').forEach((tr,i)=>{let q=bank.questions[i];for(let k of ['clue','answer','mode','fact','source'])q[k]=tr.querySelector(`[data-field="${k}"]`).value;q.aliases=tr.querySelector('[data-field="aliases"]').value.split(';').map(x=>x.trim()).filter(Boolean)})}
function renderEditor(){accent(draft);let r=draft,lv=r.levels[editLevel],b=lv.banks[editBank];app.innerHTML=head('Taller docente','Editor universal','Configura el rosco, revisa las preguntas y guarda tu trabajo.')+`<div class="stack"><section class="panel"><h2>1. Identidad del juego</h2><div class="fields" style="margin-top:12px">${field('Título','edTitle',r.title)}<label class="field"><span>Materia</span><input id="edSubject" list="subjects" value="${esc(r.subject)}"><datalist id="subjects">${options(Object.keys(colors))}</datalist></label>${sel('Curso','edCourse',[...new Set([...courses,r.course])],r.course)}${field('Autoría (opcional)','edAuthor',r.author)}${field('Color del juego','edColor',r.color,'color')}</div><label class="field"><span>Descripción</span><textarea id="edDescription" rows="2">${esc(r.description)}</textarea></label></section><section class="panel"><h2>2. Letras, niveles y bancos</h2><p class="muted">Elige qué letras utilizar. Para duelo necesitas al menos dos bancos en el mismo nivel.</p>${lettersHTML(r.letters)}<div class="row" style="margin-top:12px"><button id="applyLetters">Aplicar selección de letras</button><button id="addLevel" ${r.levels.length>=4?'disabled':''}>+ Nivel</button><button id="removeLevel" ${r.levels.length<=1?'disabled':''}>− Nivel actual</button><button id="addBank" ${lv.banks.length>=4?'disabled':''}>+ Banco</button><button id="removeBank" ${lv.banks.length<=1?'disabled':''}>− Banco actual</button></div></section><section class="panel"><div class="row between"><h2>3. Preguntas</h2><span class="pill">${count(r)} preguntas en total</span></div><div class="fields" style="margin:12px 0"><label class="field"><span>Nivel</span><select id="levelSelect">${r.levels.map((l,i)=>`<option value="${i}" ${i===editLevel?'selected':''}>${i+1}. ${esc(l.name)}</option>`).join('')}</select></label>${field('Nombre del nivel','levelName',lv.name)}<label class="field"><span>Banco</span><select id="bankSelect">${lv.banks.map((l,i)=>`<option value="${i}" ${i===editBank?'selected':''}>${i+1}. ${esc(l.name)}</option>`).join('')}</select></label>${field('Nombre del banco','bankName',b.name)}</div><div class="scroll"><table style="min-width:950px"><thead><tr><th>Letra</th><th>Tipo</th><th style="width:28%">Pregunta</th><th style="width:17%">Respuesta</th><th>Alternativas (;)</th><th>Explicación</th><th>Fuente / pág.</th></tr></thead><tbody>${b.questions.map(q=>`<tr data-q="${q.letter}"><td>${q.letter}</td><td><select data-field="mode" aria-label="Tipo ${q.letter}"><option value="starts" ${q.mode==='starts'?'selected':''}>Empieza por</option><option value="contains" ${q.mode==='contains'?'selected':''}>Contiene</option></select></td><td><textarea data-field="clue" aria-label="Pregunta ${q.letter}">${esc(q.clue)}</textarea></td><td><input data-field="answer" aria-label="Respuesta ${q.letter}" value="${esc(q.answer)}"></td><td><input data-field="aliases" aria-label="Alternativas ${q.letter}" value="${esc(q.aliases.join('; '))}"></td><td><textarea data-field="fact" aria-label="Explicación ${q.letter}">${esc(q.fact)}</textarea></td><td><input data-field="source" aria-label="Fuente ${q.letter}" value="${esc(q.source||'')}"></td></tr>`).join('')}</tbody></table></div><div id="audit" class="notice" style="margin-top:12px">Verifica las respuestas antes de jugar.</div></section><div class="toolbar row"><button class="primary" id="save">Guardar rosco</button><button id="verify">Verificar preguntas</button><button id="playDraft">Jugar</button><button id="exportDraft">Exportar JSON</button><button id="exportHtml">Descargar HTML autónomo</button><button id="printDraft">Solucionario</button><button id="newDraft">Nuevo</button></div></div>`;bindLetters();app.oninput=()=>{if(view==='editor')dirty=true};$('edSubject').onchange=()=>{$('edColor').value=colors[val('edSubject')]||'#4f46e5';dirty=true};$('levelSelect').onchange=()=>{syncEditor();editLevel=Number(val('levelSelect'));editBank=0;renderEditor()};$('bankSelect').onchange=()=>{syncEditor();editBank=Number(val('bankSelect'));renderEditor()};act('applyLetters',()=>{syncEditor();let ls=picked();if(ls.length<2)return toast('Selecciona al menos dos letras.');if(r.letters.some(l=>!ls.includes(l))&&!confirm('Se eliminarán las preguntas de las letras desmarcadas. ¿Continuar?'))return;r.letters=ls;r.levels.forEach(l=>l.banks.forEach(b=>b.questions=ls.map(x=>b.questions.find(q=>q.letter===x)||qblank(x))));dirty=true;renderEditor()});act('addLevel',()=>{syncEditor();r.levels.push(newRosco(r.letters).levels[0]);editLevel=r.levels.length-1;r.levels[editLevel].name=`Nivel ${editLevel+1}`;editBank=0;dirty=true;renderEditor()});act('removeLevel',()=>{if(confirm('¿Eliminar el nivel y sus preguntas?')){syncEditor();r.levels.splice(editLevel,1);editLevel=editBank=0;dirty=true;renderEditor()}});act('addBank',()=>{syncEditor();lv.banks.push({name:`Banco ${String.fromCharCode(65+lv.banks.length)}`,questions:r.letters.map(qblank)});editBank=lv.banks.length-1;dirty=true;renderEditor()});act('removeBank',()=>{if(confirm('¿Eliminar el banco y sus preguntas?')){syncEditor();lv.banks.splice(editBank,1);editBank=0;dirty=true;renderEditor()}});act('verify',audit);act('save',()=>{syncEditor();let i=mine.findIndex(x=>x.id===r.id);if(i<0)mine.push(clone(r));else mine[i]=clone(r);dirty=false;toast(persist()?'Rosco guardado en este navegador.':'No se pudo guardar en el navegador. Exporta JSON para conservarlo.');audit()});act('playDraft',()=>{syncEditor();if(issues(r).some(x=>x.hard))return audit();setup(clone(r))});act('exportDraft',()=>{syncEditor();exportJSON(r)});act('exportHtml',()=>{syncEditor();if(issues(r).some(x=>x.hard))return audit();exportHTML(r)});act('printDraft',()=>{syncEditor();printAnswers(r)});act('newDraft',create)}
function audit(){syncEditor();let errs=issues(draft),hard=errs.filter(x=>x.hard).length;$('audit').innerHTML=errs.length?`<strong class="${hard?'error':'success'}">${hard} errores · ${errs.length-hard} avisos</strong><details open><summary>Ver incidencias</summary>${errs.slice(0,300).map(x=>`<div>${esc(x.label)}: ${esc(x.msg)}</div>`).join('')}</details>`:'<strong class="success">✓ Todas las preguntas cumplen las comprobaciones básicas.</strong>';return hard===0}
function exportJSON(r){download(`${slug(r.title)}.json`,JSON.stringify(r,null,2))}function importText(t){t=t.trim().replace(/^```(?:json)?\s*/i,'').replace(/\s*```$/,'');draft=normalize(JSON.parse(t));dirty=true;editLevel=editBank=0;go('editor',true);audit();toast('Importado. Revisa las preguntas y guarda el rosco.')}
function exportHTML(r){let doc=document.documentElement.cloneNode(true);doc.querySelector('#app').innerHTML='';doc.querySelector('#toast').className='hidden';doc.querySelector('#catalog').textContent=JSON.stringify({portable:true,games:[r]}).replace(/</g,'\\u003c');doc.querySelector('title').textContent=r.title+' · Rosco LAB';doc.querySelector('body').className='';doc.removeAttribute('style');download(`${slug(r.title)}-PDI.html`,'<!doctype html>\n'+doc.outerHTML,'text/html;charset=utf-8');toast('HTML autónomo preparado. Puedes abrirlo sin Internet.')}
function renderAI(){app.innerHTML=head('Taller de inteligencia artificial','Crear con IA','Sube un documento o pega tus apuntes. Genera preguntas sin claves ni cuentas.')+`<div class="split"><section class="panel stack"><h2>1. Configura tu rosco</h2><div class="fields">${sel('Origen','sourceType',['PDF','Word','Texto','Tema'],'PDF')}<label class="field"><span>Materia</span><input id="aiSubject" list="aiSubjects" value="Tecnología y Digitalización"><datalist id="aiSubjects">${options(Object.keys(colors))}</datalist></label>${sel('Curso','aiCourse',courses,'3º ESO')}${sel('Dificultad','aiDifficulty',['Básica','Intermedia','Avanzada','Progresiva'],'Progresiva')}${sel('Niveles','aiLevels',['1','2','3','4'],'1')}${sel('Bancos por nivel','aiBanks',['1','2','3','4'],'1')}</div><label class="field"><span>Tema o título</span><input id="aiTitle" placeholder="Ej. Electricidad y circuitos"></label><label class="field"><span>Texto de referencia o indicaciones (opcional)</span><textarea id="aiText" rows="4" placeholder="Pega aquí tus apuntes o especifica contenidos."></textarea></label><label class="label">Letras del rosco</label>${lettersHTML(ABC)}${check('aiFact','Incluir explicaciones',true)}${check('aiStrict','Limitar al documento o texto (si se aporta)',true)}<div class="notice" id="aiCount"></div></section><section class="panel stack"><div class="row between"><h2>2. Genera tu rosco</h2><span class="pill">SIN CLAVES · V1.3</span></div><div class="row ai-tabs"><button class="primary" id="directTab" aria-pressed="true">Desde documento / texto</button><button id="promptTab" aria-pressed="false">ChatGPT · Gemini · Claude</button></div><div id="directPanel" class="stack"><div id="pdfBox" class="pdf-drop stack"><label class="field"><span id="documentLabel">Documento PDF (máx. 10 MB)</span><input type="file" id="pdfSource" accept=".pdf,application/pdf"></label><small id="pdfInfo" class="muted">Selecciona un documento con texto.</small><button id="readDocument">Leer documento</button><label id="pageBox" class="field hidden"><span>Páginas (ej. 1-3, 5; vacío = todas)</span><input id="pageRange" placeholder="Todas las páginas"></label><p id="docStatus" role="status" class="muted"></p><details id="docPreview" class="hidden"><summary>Ver texto extraído</summary><textarea id="extractedPreview" rows="6" readonly></textarea></details></div><label class="field"><span>Método de generación</span><select id="generationMethod"><option value="auto">Automático (IA local si está disponible; si no, solo definiciones)</option><option value="rules">Extracción de definiciones · sin IA</option><option value="local">IA local de Chrome · experimental</option></select></label><div class="row"><button id="checkLocal">Comprobar IA local</button><span id="localStatus" class="muted" role="status">Sin comprobar</span></div><div class="notice" id="directCost">Solo pistas de definición o preguntas completas. No se generan frases con huecos. Si faltan conceptos fiables, quedarán letras pendientes. El método usado aparece en el resultado.</div><div class="row"><button class="primary" id="directGenerate">✦ Generar borrador</button><button id="directCancel" class="hidden">Cancelar</button><button id="directPartial" class="hidden">Revisar borrador</button></div><progress id="directProgress" class="hidden" value="0" max="1"></progress><p id="directStatus" role="status" aria-live="polite" class="muted"></p><div id="candidateBox" class="hidden stack"><div id="candidateSummary" class="notice"></div><div class="row"><button id="alternativeDraft">Probar otras preguntas</button><button id="trimDraft">Usar solo letras completas</button></div><details><summary>Ver conceptos detectados</summary><div id="candidateList" class="muted"></div></details></div><small>El PDF se lee en tu navegador. Los documentos escaneados sin texto no son compatibles con esta versión. Revisa siempre el resultado y las páginas indicadas.</small></div><div class="stack hidden" id="promptPanel"><h3>Asistente con tu IA habitual</h3><div class="notice" id="aiInstructions"></div><textarea id="prompt" rows="15" readonly aria-label="Prompt generado"></textarea><div class="row"><button class="primary" id="copyPrompt">Copiar prompt</button><a class="btn" href="https://chatgpt.com/" target="_blank" rel="noopener">ChatGPT ↗</a><a class="btn" href="https://gemini.google.com/" target="_blank" rel="noopener">Gemini ↗</a></div><a class="btn" href="https://claude.ai/" target="_blank" rel="noopener">Claude ↗</a><small>No adjuntes datos personales del alumnado. Revisa las respuestas antes de jugar.</small></div></section></div><section class="panel" style="margin-top:16px"><h2>3. Importa el resultado</h2><p class="muted">Pega el JSON generado por la IA o abre su archivo. Pasarás al editor para revisar y guardar.</p><textarea id="importText" rows="6" placeholder="Pega aquí el JSON…"></textarea><div class="row" style="margin-top:10px"><button class="primary" id="importPaste">Importar y revisar</button><button id="importFile">Abrir archivo JSON</button><input type="file" id="aiFile" accept=".json,application/json" hidden></div><p id="importError" class="error" role="alert"></p></section>`;bindLetters();app.oninput=()=>{if(view==='ai')updatePrompt()};app.onchange=()=>{if(view==='ai')updatePrompt()};act('copyPrompt',async()=>{try{await navigator.clipboard.writeText(val('prompt'));toast('Prompt copiado.')}catch{$('prompt').focus();$('prompt').select();toast('Seleccionado: pulsa Ctrl+C para copiar.')}});act('importPaste',()=>{try{importText(val('importText'))}catch(e){$('importError').textContent=e.message}});act('importFile',()=>$('aiFile').click());$('aiFile').onchange=async()=>{try{importText(await $('aiFile').files[0].text())}catch(e){$('importError').textContent=e.message}};bindDirect();updatePrompt()}
function updatePrompt(){let ls=picked(),n=Number(val('aiLevels')),b=Number(val('aiBanks')),src=val('sourceType'),r=newRosco(ls,n,b);r.title=val('aiTitle')||'Mi rosco educativo';r.subject=val('aiSubject');r.course=val('aiCourse');r.color=colors[r.subject]||'#4f46e5';let sample={schema:r.schema,title:r.title,subject:r.subject,course:r.course,author:'',description:'Descripción breve',color:r.color,letters:ls,levels:[{name:'Básico',banks:[{name:'Banco A',questions:[{letter:ls[0]||'A',mode:'starts',clue:'Pregunta de ejemplo',answer:'Respuesta que cumple la letra',fact:'Explicación breve',aliases:[],source:'Página si se conoce'}]}]}]};$('aiCount').textContent=`${ls.length} letras × ${n} niveles × ${b} bancos = ${ls.length*n*b} preguntas. ${ls.length<2?'Selecciona al menos 2 letras.':''}`;$('copyPrompt').disabled=ls.length<2;$('aiInstructions').textContent=['PDF','Word'].includes(src)?'Abre ChatGPT, Gemini o Claude, adjunta allí el documento y pega el prompt.':src==='Texto'?'Pega tus apuntes en el campo de texto y después copia el prompt a tu IA.':'Copia el prompt en tu IA para crear preguntas sobre el tema elegido.';$('prompt').value=`Actúa como docente especialista. Genera un rosco educativo compatible con Rosco LAB.\nMateria: ${r.subject}\nCurso: ${r.course}\nTítulo: ${r.title}\nDificultad: ${val('aiDifficulty')}\nOrigen: ${src}\n${val('aiText')?'Contenido/indicaciones:\n'+val('aiText')+'\n':''}${['PDF','Word'].includes(src)?'Lee el documento adjunto a esta conversación.\n':''}${src!=='Tema'&&$('aiStrict').checked?'Usa exclusivamente la información del material aportado. Si no puedes construir todas las letras, pide ajustar la selección antes de emitir JSON; no inventes hechos.\n':''}Crea exactamente ${n} niveles y ${b} bancos diferentes por nivel. En cada banco incluye exactamente una pregunta por cada letra de ${ls.join(', ')} en ese orden. Total: ${ls.length*n*b}. No repitas respuestas en un banco ni entre bancos del mismo nivel. Usa mode "starts" si la solución empieza por la letra, "contains" si la contiene. Respeta la Ñ como letra distinta de N. Redacta pistas de definición autónomas, como en Pasapalabra, o preguntas completas. Ejemplo: Unidad de medida de la intensidad eléctrica. Respuesta: Amperio. Prohibido completar frases, rellenar huecos, sustituir palabras por guiones, copiar fragmentos incompletos o usar pistas vagas. Si no hay un concepto válido, no lo fuerces. Enunciados claros y sin incluir la solución. aliases: alternativas completas válidas o []. ${$('aiFact').checked?'Incluye una explicación en fact.':'Deja fact como cadena vacía.'} En source cita la página del PDF si es verificable, o deja vacío. No inventes referencias.\nDevuelve solo JSON válido, sin comentarios ni Markdown, con esta estructura (ejemplo abreviado, debes completar todas las letras, niveles y bancos):\n${JSON.stringify(sample,null,2)}`;refreshDirect()}
let selected=null;function setup(r){selected=clone(r);go('setup',true)}function renderSetup(){let r=selected;accent(r);app.innerHTML=head(esc(r.subject)+' · '+esc(r.course),esc(r.title),'Configura la partida antes de empezar.')+`<div class="split"><section class="panel stack"><h2>Configuración</h2><label class="field"><span>Nivel</span><select id="gLevel">${r.levels.map((l,i)=>`<option value="${i}">${esc(l.name)}</option>`).join('')}</select></label><label class="field"><span>Modo de juego</span><select id="gMode"><option value="solo">Individual / clase</option><option value="duel">Duelo de equipos</option></select></label><div id="bankChoices" class="stack"></div><label class="field"><span>Tiempo por equipo</span><select id="gTime"><option value="0">Sin límite</option><option value="60">1 minuto</option><option value="120">2 minutos</option><option value="180">3 minutos</option><option value="300" selected>5 minutos</option><option value="600">10 minutos</option></select></label>${sel('Respuesta','gAnswer',['Escrita y automática','Oral / manual'],'Escrita y automática')}${check('gHints','Permitir pistas',true)}${check('gSound','Sonidos',true)}<button id="start" class="primary">Comenzar partida →</button></section><section class="panel stack"><h2>${esc(r.title)}</h2><p>${esc(r.description)}</p><div class="row"><span class="pill">${r.letters.length} letras</span><span class="pill">${count(r)} preguntas</span></div><p>Selecciona el nivel y el banco. En duelo cada equipo tiene su propio rosco y cronómetro. El turno cambia al fallar o pasar.</p><div class="row"><button id="setupExport">Descargar HTML autónomo</button><button id="setupPrint">Solucionario</button></div><button id="backLibrary">Volver a biblioteca</button></section></div>`;function banks(){let l=r.levels[Number(val('gLevel'))];let duel=$('gMode').options[1];duel.disabled=l.banks.length<2;if(duel.disabled&&val('gMode')==='duel')$('gMode').value='solo';let opts=l.banks.map((b,i)=>`<option value="${i}">${esc(b.name)}</option>`).join('');let d=val('gMode')==='duel';$('bankChoices').innerHTML=`<label class="field"><span>Banco ${d?'equipo A':''}</span><select id="gBankA">${opts}</select></label>${d?`<label class="field"><span>Banco equipo B</span><select id="gBankB">${opts}</select></label>${field('Nombre equipo A','gNameA','Equipo A')}${field('Nombre equipo B','gNameB','Equipo B')}${check('gDraw','Sortear qué equipo empieza',true)}`:''}`;if(d)$('gBankB').selectedIndex=1}$('gLevel').onchange=banks;$('gMode').onchange=banks;banks();act('start',()=>{let d=val('gMode')==='duel',a=Number(val('gBankA')),b=d?Number(val('gBankB')):0;if(d&&a===b)return toast('Elige bancos distintos para el duelo.');let lv=r.levels[Number(val('gLevel'))],time=Number(val('gTime'));game={r:clone(r),level:lv.name,teams:(d?[a,b]:[a]).map((idx,i)=>({name:d?(val(i?'gNameB':'gNameA').trim()||`Equipo ${i+1}`):'Clase',questions:clone(lv.banks[idx].questions),status:r.letters.map(()=>0),cursor:0,time:time*1000,hints:3,hintText:'',answers:{}})),active:d&&$('gDraw').checked?Math.floor(Math.random()*2):0,duration:time,manual:val('gAnswer')==='Oral / manual',hints:$('gHints').checked,sound:$('gSound').checked,paused:false,finished:false,undo:null,feedback:'',last:performance.now()};go('game',true);startTimer()});act('setupExport',()=>exportHTML(r));act('setupPrint',()=>printAnswers(r));act('backLibrary',()=>go('library'))}
const team=()=>game.teams[game.active],current=()=>team().questions[team().cursor],stats=t=>({good:t.status.filter(x=>x===1).length,bad:t.status.filter(x=>x===2).length,left:t.status.filter(x=>x===0).length}),can=t=>stats(t).left>0&&(!game.duration||t.time>0),timeFmt=t=>game.duration?`${String(Math.floor(Math.ceil(t.time/1000)/60)).padStart(2,'0')}:${String(Math.ceil(t.time/1000)%60).padStart(2,'0')}`:'∞';function sound(good){if(!game.sound)return;try{const ctx=new (window.AudioContext||window.webkitAudioContext)(),o=ctx.createOscillator(),g=ctx.createGain();o.connect(g);g.connect(ctx.destination);o.frequency.value=good?650:200;g.gain.value=.06;o.start();o.stop(ctx.currentTime+.15);o.onended=()=>ctx.close()}catch{}}function nextCursor(t){for(let i=1;i<=t.status.length;i++){let n=(t.cursor+i)%t.status.length;if(t.status[n]===0){t.cursor=n;return}}}function snapshot(){let s=clone({...game,undo:null});game.undo=s}function switchIfNeeded(force){if(!game.teams.some(can)){finish();return}if(game.teams.length>1&&(force||!can(team()))&&can(game.teams[1-game.active]))game.active=1-game.active;if(!can(team()))game.active=game.teams.findIndex(can)}function mark(status,typed=''){if(game.paused||game.finished||!can(team()))return;snapshot();let t=team(),q=current();t.status[t.cursor]=status;t.answers[t.cursor]=typed;t.hintText='';game.feedback=`${status===1?'✓ Acierto':'✗ Fallo'} · ${q.answer}${q.fact?' — '+q.fact:''}`;sound(status===1);nextCursor(t);switchIfNeeded(status===2);if(!game.finished)renderGame()}
function pass(){if(game.paused||game.finished)return;snapshot();team().hintText='';nextCursor(team());game.feedback='Letra pasada. Podrás volver a ella.';switchIfNeeded(true);if(!game.finished)renderGame()}
function startTimer(){clearInterval(timer);game.last=performance.now();timer=setInterval(()=>{if(view!=='game'||game.finished||game.paused){game.last=performance.now();return}let now=performance.now(),d=now-game.last;game.last=now;if(game.duration){let t=team();t.time=Math.max(0,t.time-d);if(t.time<=0){game.feedback=`Se acabó el tiempo de ${t.name}.`;switchIfNeeded(true);if(!game.finished)renderGame()}else{if($('clock'))$('clock').textContent=timeFmt(t);game.teams.forEach((x,i)=>{if($('time'+i))$('time'+i).textContent=timeFmt(x)})}}},100)}
function renderGame(){accent(game.r);let t=team(),q=current(),s=stats(t),n=t.questions.length;app.innerHTML=`<div class="row between" style="margin-bottom:14px"><div><span class="pill">${esc(game.level)}</span> <strong>${esc(game.r.title)}</strong></div><div class="row"><button id="pdi">Modo PDI</button><button id="full">Pantalla completa</button><button id="pause">${game.paused?'Reanudar':'Pausa'}</button><button id="end">Finalizar</button></div></div><div class="game-layout"><section class="panel"><div class="scores">${game.teams.map((x,i)=>{let y=stats(x);return `<div class="${i===game.active?'active-team':''}"><strong>${esc(x.name)}</strong> · <span id="time${i}">${timeFmt(x)}</span><br><small>✓ ${y.good} · ✗ ${y.bad} · Pend. ${y.left}</small></div>`}).join('')}</div><div class="wheel">${t.questions.map((x,i)=>{let a=i*2*Math.PI/n-Math.PI/2;return `<button class="wheel-letter ${t.status[i]===1?'correct':t.status[i]===2?'wrong':i===t.cursor?'current':''}" style="left:${50+43.8*Math.cos(a)}%;top:${50+43.8*Math.sin(a)}%;${n>23?'width:9%;height:9%':''}" aria-label="Letra ${x.letter}, ${t.status[i]===1?'acertada':t.status[i]===2?'fallada':'pendiente'}" data-jump="${i}" ${t.status[i]||game.paused?'disabled':''}>${x.letter}</button>`}).join('')}<div class="wheel-center"><span class="muted">${esc(t.name)}</span><div class="clock" id="clock">${timeFmt(t)}</div><strong>${s.good}/${n} aciertos</strong><small>${s.left} pendientes</small></div></div></section><section class="panel"><div class="row between"><span class="pill">TURNO · ${esc(t.name)}</span><span class="letter-big">${q.letter}</span></div><div class="eyebrow muted">${q.mode==='starts'?'Empieza por':'Contiene la'} ${q.letter}</div><div class="question">${game.paused?'Partida en pausa':esc(q.clue)}</div>${game.paused?'':`<div class="no-print">${game.manual?`<div class="row"><button class="good" id="correct">✓ Acierto</button><button class="bad" id="wrong">✗ Fallo</button></div>`:`<form id="answerForm" class="row"><input id="typed" aria-label="Escribe tu respuesta" placeholder="Escribe tu respuesta" autocomplete="off" style="flex:1;min-width:150px"><button class="primary" type="submit">Comprobar</button></form>`}<div class="row" style="margin-top:12px"><button id="pass">Pasapalabra →</button><button id="reveal">Ver solución</button>${game.hints?`<button id="hint" ${!t.hints?'disabled':''}>Pista (${t.hints})</button>`:''}<button id="undo" ${game.undo?'':'disabled'}>Deshacer</button></div><p id="solution" class="hidden notice">${esc(q.answer)}${q.fact?' · '+esc(q.fact):''}</p><p class="muted">${esc(t.hintText)}</p></div>`}<div class="feedback" role="status">${esc(game.feedback)}</div></section></div>`;app.querySelectorAll('[data-jump]').forEach(b=>b.onclick=()=>{snapshot();t.cursor=Number(b.dataset.jump);t.hintText='';renderGame()});act('pdi',()=>document.body.classList.toggle('pdi'));act('full',()=>{if(document.fullscreenElement)document.exitFullscreen?.();else document.documentElement.requestFullscreen?.().catch(()=>toast('Usa F11 para pantalla completa.'))});act('pause',()=>{game.paused=!game.paused;game.last=performance.now();renderGame()});act('end',()=>{if(confirm('¿Finalizar la partida y ver resultados?'))finish()});act('correct',()=>mark(1));act('wrong',()=>mark(2));act('pass',pass);act('undo',undo);act('reveal',()=>{$('solution').classList.toggle('hidden')});act('hint',()=>{if(t.hints){snapshot();t.hints--;t.hintText=`Pista: ${q.answer.trim().slice(0,1).toUpperCase()}… · ${q.answer.trim().length} caracteres (incluidos espacios).`;renderGame()}});if($('answerForm')){$('answerForm').onsubmit=e=>{e.preventDefault();let a=val('typed');if(!norm(a))return toast('Escribe una respuesta.');mark([q.answer,...q.aliases].some(x=>norm(x)===norm(a))?1:2,a)};$('typed').focus()}}
function undo(){if(!game.undo)return;game=game.undo;game.undo=null;game.finished=false;game.last=performance.now();go('game',true);startTimer()}function finish(){game.finished=true;clearInterval(timer);go('result',true)}function renderResult(){accent(game.r);let top=Math.max(...game.teams.map(t=>stats(t).good)),w=game.teams.filter(t=>stats(t).good===top);app.innerHTML=head('Fin de partida',game.teams.length===1?'¡Buen trabajo!':w.length===1?`¡Gana ${esc(w[0].name)}!`:'¡Empate!','Revisa las respuestas y vuelve a intentarlo.')+`<div class="grid">${game.teams.map(t=>{let s=stats(t);return `<section class="panel"><h2>${esc(t.name)}</h2><div class="clock" style="color:var(--accent);margin:14px 0">${s.good}/${t.questions.length}</div><p>✓ ${s.good} aciertos · ✗ ${s.bad} fallos · ${s.left} pendientes</p></section>`}).join('')}</div><div class="panel" style="margin-top:16px"><h2>Repaso de errores y pendientes</h2>${game.teams.map(t=>`<h3 style="margin:16px 0 8px">${esc(t.name)}</h3><div class="scroll"><table><thead><tr><th>Letra</th><th>Pregunta</th><th>Respuesta dada</th><th>Solución</th><th>Explicación</th></tr></thead><tbody>${t.questions.map((q,i)=>t.status[i]===1?'':`<tr><td>${q.letter}</td><td>${esc(q.clue)}</td><td>${esc(t.answers[i]|| (t.status[i]===2?'Fallo manual':'Pendiente'))}</td><td>${esc(q.answer)}</td><td>${esc(q.fact)}</td></tr>`).join('')||'<tr><td colspan="5">¡Todas acertadas!</td></tr>'}</tbody></table></div>`).join('')}<div class="row no-print" style="margin-top:15px"><button class="primary" id="again">Nueva partida</button><button id="undoEnd" ${game.undo?'':'disabled'}>Deshacer última acción</button><button id="printResult">Imprimir resultados</button><button id="libResult">Biblioteca</button></div></div>`;act('again',()=>setup(game.r));act('undoEnd',undo);act('printResult',()=>window.print());act('libResult',()=>go('library'))}
function printAnswers(r){let w=window.open('','_blank');if(!w)return toast('Permite ventanas emergentes para abrir el solucionario.');w.document.write(`<!doctype html><html lang="es"><meta charset="utf-8"><title>Solucionario · ${esc(r.title)}</title><style>body{font:15px system-ui;margin:25px;color:#18253d}table{border-collapse:collapse;width:100%;margin-bottom:22px}td,th{padding:7px;border:1px solid #ccc;text-align:left}tr{break-inside:avoid}h2{break-after:avoid}@media print{button{display:none}}</style><h1>${esc(r.title)}</h1><p>${esc(r.subject)} · ${esc(r.course)} · ${esc(r.author)}</p><button onclick="print()">Imprimir / guardar PDF</button>${r.levels.map(l=>l.banks.map(b=>`<h2>${esc(l.name)} · ${esc(b.name)}</h2><table><thead><tr><th>Letra</th><th>Pregunta</th><th>Solución</th><th>Explicación / fuente</th></tr></thead><tbody>${b.questions.map(q=>`<tr><td>${q.letter}</td><td>${esc(q.clue)}</td><td>${esc(q.answer)}</td><td>${esc(q.fact)} ${esc(q.source||'')}</td></tr>`).join('')}</tbody></table>`).join('')).join('')}<p>Rosco LAB · Tecnología Insti</p></html>`);w.document.close()}
function help(){app.innerHTML=head('Guía rápida','Cómo usar Rosco LAB','No necesitas una cuenta para crear o jugar.')+`<div class="grid"><article class="panel"><h2>Crear manualmente</h2><p>Abre Crear rosco, selecciona las letras y pulsa Aplicar selección. Añade niveles y bancos. Completa cada pregunta y respuesta. Verifica y guarda.</p></article><article class="panel"><h2>Crear desde PDF o tema</h2><p>Abre Crear con IA, elige PDF, Word, Texto o Tema. Lee el documento y genera un borrador mediante extracción de conceptos o IA local si tu navegador es compatible. También puedes copiar el prompt a ChatGPT, Gemini o Claude e importar el JSON.</p></article><article class="panel"><h2>Compartir y jugar sin conexión</h2><p>Exporta JSON para editar en otro dispositivo o HTML autónomo para jugar sin conexión. Guarda los archivos: los roscos de Mis roscos se almacenan solo en tu navegador.</p></article><article class="panel"><h2>Duelo y revisión</h2><p>Crea dos bancos de preguntas por nivel. Selecciona duelo, asigna un banco distinto a cada equipo y configura el tiempo. Al final podrás revisar errores.</p></article><article class="panel"><h2>Privacidad y revisión</h2><p>La web no requiere cuentas. El extractor y la IA local procesan el texto en tu dispositivo. La primera carga del lector PDF y del modelo local puede requerir Internet. Si usas una IA externa, tú decides qué material compartir. Evita datos personales o materiales que no tengas derecho a compartir. Comprueba la corrección de cada pregunta.</p></article><article class="panel"><h2>Edición Andalucía original</h2><p>El juego 4D V5.2 conserva sus funciones y su diseño propios.</p>${portable?'':'<a class="btn" href="andalucia/index.html">Abrir edición 4D</a>'}</article></div>`}
