async function readDocx(buffer){const v=new DataView(buffer),u=new Uint8Array(buffer);let end=-1;for(let i=u.length-22;i>=Math.max(0,u.length-65557);i--)if(v.getUint32(i,true)===0x06054b50){end=i;break}if(end<0)throw Error('Word no válido: se requiere .docx.');let pos=v.getUint32(end+16,true),n=v.getUint16(end+10,true),xml;for(let i=0;i<n;i++){if(v.getUint32(pos,true)!==0x02014b50)throw Error('Archivo Word dañado.');let method=v.getUint16(pos+10,true),size=v.getUint32(pos+20,true),unpacked=v.getUint32(pos+24,true),nl=v.getUint16(pos+28,true),xl=v.getUint16(pos+30,true),cl=v.getUint16(pos+32,true),off=v.getUint32(pos+42,true),name=new TextDecoder().decode(u.subarray(pos+46,pos+46+nl));if(name==='word/document.xml'){if(unpacked>12*1048576)throw Error('El documento Word es demasiado grande.');let start=off+30+v.getUint16(off+26,true)+v.getUint16(off+28,true),data=u.subarray(start,start+size);if(method===8){data=new Uint8Array(await new Response(new Blob([data]).stream().pipeThrough(new DecompressionStream('deflate-raw'))).arrayBuffer())}else if(method!==0)throw Error('Compresión Word no compatible.');xml=new TextDecoder().decode(data);break}pos+=46+nl+xl+cl}if(!xml)throw Error('No se encontró el contenido Word.');let doc=new DOMParser().parseFromString(xml,'application/xml');if(doc.querySelector('parsererror'))throw Error('Contenido Word no válido.');return [...doc.getElementsByTagNameNS('*','p')].map(p=>[...p.getElementsByTagNameNS('*','t')].map(t=>t.textContent).join('')).join('\n')}
async function extractFile(file,signal){if(!file)throw Error('Selecciona un archivo.');if(file.size>10*1048576)throw Error('El archivo supera 10 MB.');const ext=file.name.split('.').pop().toLowerCase();if(ext==='txt')return [{page:null,text:await file.text()}];if(ext==='docx')return [{page:null,text:await readDocx(await file.arrayBuffer())}];if(ext!=='pdf')throw Error('Formato no compatible. Usa PDF, DOCX o TXT.');let lib=await pdfLibrary();signal.throwIfAborted();let task=lib.getDocument({data:new Uint8Array(await file.arrayBuffer()),isEvalSupported:false,disableFontFace:true});let abort=()=>task.destroy().catch(()=>{});signal.addEventListener('abort',abort,{once:true});try{let pdf=await task.promise,arr=[];if(pdf.numPages>250)throw Error('El PDF supera 250 páginas. Divide el documento en partes.');for(let p=1;p<=pdf.numPages;p++){signal.throwIfAborted();let page=await pdf.getPage(p),tc=await page.getTextContent(),text=tc.items.map(x=>typeof x.str==='string'?x.str+(x.hasEOL?'\n':' '):'').join('');arr.push({page:p,text});if($('docStatus'))$('docStatus').textContent=`Leyendo página ${p} de ${pdf.numPages}…`;if($('directProgress'))$('directProgress').value=p/pdf.numPages;page.cleanup()}return arr}finally{signal.removeEventListener('abort',abort);await task.destroy().catch(()=>{})}}
