function collectCandidates(pages){let pool=new Map();for(let {page,text} of pages){let normalized=text.replace(/\r/g,'').replace(/(\p{L})-\n(?=\p{Ll})/gu,'$1');let segments=[...normalized.split(/\n+/),...normalized.replace(/([^\n])\n(?=\p{Ll})/gu,'$1 ').split(/(?<=[.!?])\s+|\n+/)];for(let line of segments){line=line.replace(/\s+/g,' ').trim();if(line.length>450||!/[.!?]$/.test(line))continue;let m=line.match(/^(.{2,65}?)\s*(?::|\s[–—]\s|\s(?:es|son|se define como|se denomina)\s)\s*(.{15,380})$/iu);if(!m)continue;let term=cleanTerm(m[1]),clue=m[2].trim();if(!termOK(term)||/[.!?;,:=()\d]/.test(term)||/\b(?:es|son|tiene[n]?|consume[n]?|utiliza[n]?|puede[n]?|consta[n]?|cuando|porque|si|que|cómo|ejemplo|actividad|ejercicio|pregunta)\b/iu.test(term))continue;if(!definitionStart.test(clue)||!goodClue(clue,term))continue;clue=clue.charAt(0).toLocaleUpperCase('es')+clue.slice(1);let key=norm(term);if(!pool.has(key))pool.set(key,{term,clue,source:page?'Página '+page:'',score:100,context:line})}}return [...pool.values()].sort((a,b)=>a.term.localeCompare(b.term,'es'))}
