function buildRules(cfg,pool,round=0){let r=clone(cfg.r),globalUsed=new Set();r.description='Borrador por extracción de definiciones explícitas del material. Revisar antes de jugar; la dificultad no está calibrada automáticamente.';for(let lv of r.levels){let levelUsed=new Set();for(let bank of lv.banks){let lists=new Map(r.letters.map(l=>{let matches=pool.filter(c=>!levelUsed.has(norm(c.term))&&norm(c.term).includes(norm(l)));matches.sort((a,b)=>{const rank=c=>(norm(c.term).startsWith(norm(l))?1000:0)+(globalUsed.has(norm(c.term))?0:200)+c.score;return rank(b)-rank(a)});if(round&&matches.length>1){let cut=round%Math.min(5,matches.length);matches=[...matches.slice(cut),...matches.slice(0,cut)]}return [l,matches]}));let owner=new Map(),assignment=new Map();function place(l,visited){for(const c of lists.get(l)){let k=norm(c.term);if(visited.has(k))continue;visited.add(k);let prev=owner.get(k);if(!prev||place(prev,visited)){owner.set(k,l);assignment.set(l,c);return true}}return false}for(let l of [...r.letters].sort((a,b)=>lists.get(a).length-lists.get(b).length))place(l,new Set());bank.questions=r.letters.map(l=>{let c=assignment.get(l);if(!c)return qblank(l);levelUsed.add(norm(c.term));globalUsed.add(norm(c.term));return {letter:l,mode:norm(c.term).startsWith(norm(l))?'starts':'contains',clue:c.clue,answer:c.term,fact:cfg.facts?c.context:'',aliases:[],source:c.source}})}}return r}
